# lib/kollective/civic/token_schema.ex
defmodule Kollective.Civic.TokenSchema do
  # Universally enforces chronological Ecto.ULID primary keys and UTC datetime logging option profiles [INDEX]
  use Kollective.Schemas.Schema

  # Overwrites the URL parameter mapping so Phoenix routes see the token text string cleanly if needed
  @derive {Phoenix.Param, key: :token}

  schema "vouch_secure_tokens" do
    # Primary id field using sortable Ecto.ULID is automatically generated by our macro! [INDEX]
    field :token, :string
    field :expires_at, :utc_datetime

    belongs_to :user, Kollective.Accounts.User, foreign_key: :user_id

    # Keeps the table declarations clean and consistent
    timestamps()
  end

  @doc """
  Validates input token arguments before committing to Postgres [INDEX].
  """
  def changeset(token_schema, attrs) do
    token_schema
    |> cast(attrs, [:token, :user_id, :expires_at])
    |> validate_required([:token, :user_id, :expires_at])
    |> validate_length(:token, min: 10, max: 255)
    # Enforces database uniqueness on the token text string column cleanly [INDEX]
    |> unique_constraint(:token, name: :vouch_secure_tokens_token_index)
  end
end
